        todoList.appendChild(li);
      });
    }
    this.renderUI();
};
```

So `render` only creates li elements for items that match the current filter. When we do in-place mutation and call `renderUI`, the toggled item's li is still in the DOM even if the filter would hide it.

The fix: if the filter would hide the toggled item, remove the li from its parent. Otherwise, just do in-place mutation.

